using Domain.Seedwork.Specification; using System; namespace Domain.MainBoundedContext.InventoryModule.Aggregates.AssetAgg { public static class AssetSpecifications { public static Specification<Asset> Find(string text) { Specification<Asset> s=new TrueSpecification<Asset>(); if(!String.IsNullOrWhiteSpace(text)) s &= new DirectSpecification<Asset>(x=>x.Name.Contains(text)||x.SerialNumber.Contains(text)||x.TagNumber.Contains(text)); return s; } } }
